import { Node } from 'cc';

declare module 'cc' {
    interface Node {
        /**x轴坐标 */
        x: number,
        /**y轴坐标 */
        y: number,
        /**z轴坐标 */
        z: number,
        /**x轴缩放 */
        scaleX: number,
        /**y轴缩放 */
        scaleY: number,
        /**z轴缩放 */
        scaleZ: number,
        /**x轴旋转 */
        angleX: number,
        /**y轴旋转 */
        angleY: number,
        /**z轴旋转, 等同于angle */
        angleZ: number,
    }
}

Object.defineProperty(Node.prototype, 'x', {
    get: function () {
        return this.position.x;
    },
    set: function (v: number) {
        this.setPosition(v, this.position.y, this.position.z);
    },
    enumerable: true,
    configurable: true,
});

Object.defineProperty(Node.prototype, 'y', {
    get: function () {
        return this.position.y;
    },
    set: function (v: number) {
        this.setPosition(this.position.x, v, this.position.z);
    },
    enumerable: true,
    configurable: true,
});

Object.defineProperty(Node.prototype, 'z', {
    get: function () {
        return this.position.z;
    },
    set: function (v: number) {
        this.setPosition(this.position.x, this.position.y, v);
    },
    enumerable: true,
    configurable: true,
});

Object.defineProperty(Node.prototype, 'scaleX', {
    get: function () {
        return this.scale.x;
    },
    set: function (v: number) {
        this.setScale(v, this.scale.y, this.scale.z);
    },
    enumerable: true,
    configurable: true,
});

Object.defineProperty(Node.prototype, 'scaleY', {
    get: function () {
        return this.scale.y;
    },
    set: function (v: number) {
        this.setScale(this.scale.x, v, this.scale.z);
    },
    enumerable: true,
    configurable: true,
});

Object.defineProperty(Node.prototype, 'scaleZ', {
    get: function () {
        return this.scale.z;
    },
    set: function (v: number) {
        this.setScale(this.scale.x, this.scale.y, v);
    },
    enumerable: true,
    configurable: true,
});

Object.defineProperty(Node.prototype, 'angleX', {
    get: function () {
        return this.eulerAngles.x;
    },
    set: function (v: number) {
        this.setRotationFromEuler(v, this.eulerAngles.y, this.eulerAngles.z);
    },
    enumerable: true,
    configurable: true,
});

Object.defineProperty(Node.prototype, 'angleY', {
    get: function () {
        return this.eulerAngles.y;
    },
    set: function (v: number) {
        this.setRotationFromEuler(this.eulerAngles.x, v, this.eulerAngles.z);
    },
    enumerable: true,
    configurable: true,
});

Object.defineProperty(Node.prototype, 'angleZ', {
    get: function () {
        return this.eulerAngles.z;
    },
    set: function (v: number) {
        this.setRotationFromEuler(this.eulerAngles.x, this.eulerAngles.y, v);
    },
    enumerable: true,
    configurable: true,
});